func isValid(s string) bool {
	closeToOpen := map[byte]byte{')': '(', ']': '[', '}': '{'}
	stack := []byte{}
	for i := range s {
		if v, ok := closeToOpen[s[i]]; ok {
			if len(stack) > 0 {
				prev := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				if prev != v {
					return false
				}
			} else {
				return false
			}
		} else {
			stack = append(stack, s[i])
		}
	}
	return len(stack) == 0
}
